function [hd] = rotor_coast(h, jrot, viscous, coulomb)
%ROTOR_COAST  A failed rotor's momentum rate [N m]: its viscous and Coulomb friction alone (inertia jrot).
%   h: real[1] (passed a plain number)
%   jrot: real[1] (passed a plain number)
%   viscous: real[1] (passed a plain number)
%   coulomb: real[1] (passed a plain number)
%   returns hd: real[1] (passed a plain number)
%   Generated by tools/pcode.py from the pseudocode (trinetra-pcode/2); do not edit.
    hd = 0;
    hd = ((((-(viscous)) * h) / jrot) - (coulomb * sign(h)));
end
